def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally opponent behavior and own recent actions
    opp_c = 0
    opp_d = 0
    last_mine = 'C'
    last_opp = 'C'
    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        last_mine = a
        last_opp = b

    # Establish trust early; mirror a first defection only lightly
    if n <= 2:
        return 'C'
    if n == 3:
        if opp_d >= 2:
            return 'D'
        return 'C'

    opp_rate = opp_c / n
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c

    # All-cooperate: keep cooperating, tiny late-game probing
    if opp_d == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # All-defect: stop being exploited
    if opp_c == 0:
        return 'D'

    # Recent window analysis
    window = history[-12:]
    rec_opp_c = 0
    rec_opp_d = 0
    rec_mine_c = 0
    for i in range(len(window)):
        a, b = window[i]
        if b == 'C':
            rec_opp_c += 1
        else:
            rec_opp_d += 1
        if a == 'C':
            rec_mine_c += 1
    rec_len = len(window)
    rec_rate = rec_opp_c / rec_len

    # Consecutive opponent defections
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_d += 1
        else:
            break

    # Consecutive opponent cooperations
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_c += 1
        else:
            break

    # Mirror check: does opponent copy our previous move?
    if n >= 8:
        mirror = 0
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mirror += 1
        mirror_rate = mirror / (n - 1)
        if mirror_rate > 0.65:
            # Cooperative partner: give C, but exploit at very end
            if n >= 97:
                return 'D'
            return 'C'

    # Late-game: secure mutual cooperation, exploit only in final rounds
    remaining = 100 - n
    if remaining <= 2:
        if rec_rate > 0.35:
            return 'D'
        return 'D'

    # Very hostile opponent: defend but offer rare repair
    if rec_rate < 0.2 or consec_d >= 4:
        if n % 13 == 0 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Moderately hostile: retaliate but try to break the cycle
    if rec_rate < 0.45:
        if consec_d >= 2:
            # After sustained defection, mostly defect but reach out periodically
            if n % 7 == 0 or rng.random() < 0.12:
                return 'C'
            return 'D'
        if last_opp == 'D':
            # Single recent defection: retaliate once, then return to C
            return 'D'
        return 'C'

    # Cooperative opponent (rec_rate >= 0.45)

    # If opponent just cooperated, reward with cooperation
    if last_opp == 'C':
        # If we defected last, repair by cooperating
        if last_mine == 'D':
            return 'C'
        # Rare probing when cooperation is well established and we're not near the end
        if remaining > 8 and rec_rate > 0.75 and n % 19 == 0:
            if rng.random() < 0.08:
                return 'D'
        return 'C'

    # Opponent defected after otherwise cooperative play: short punishment
    if consec_d == 1:
        # Retaliate once, then plan to forgive and rebuild
        return 'D'

    # Two or more defections in a cooperative context: punish briefly then forgive
    if consec_d == 2:
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Longer defection streak despite cooperative history: defend, probe for repair
    if n % 11 == 0 or rng.random() < 0.15:
        return 'C'
    return 'D'
